#include <stddef.h>
#include <string.h>

size_t longest(const char *words[], size_t count)
{
    size_t best = 0;
    for (size_t i = 1; i < count; i++) {
        if (strlen(words[i]) > strlen(words[best])) best = i;
    }
    return best;
}

void sort_words(const char *words[], size_t count)
{
    for (size_t i = 1; i < count; i++) {
        const char *current = words[i];
        size_t j = i;
        while (j > 0 && strcmp(words[j - 1], current) > 0) {
            words[j] = words[j - 1];
            j--;
        }
        words[j] = current;
    }
}

size_t split(char *line, char *parts[], size_t max)
{
    size_t count = 0;
    char *p = line;
    while (*p != '\0' && count < max) {
        while (*p == ' ') p++;
        if (*p == '\0') break;
        parts[count++] = p;
        while (*p != '\0' && *p != ' ') p++;
        if (*p == ' ') {
            *p = '\0';
            p++;
        }
    }
    return count;
}

void advance(const char **cursor, size_t n)
{
    while (n > 0 && **cursor != '\0') {
        (*cursor)++;
        n--;
    }
}

