TEST("the longest word") { const char *w[] = {"fig", "banana", "cherry", "kiwi"}; CHECK_EQ(longest(w, 4), (size_t)1); const char *one[] = {"solo"}; CHECK_EQ(longest(one, 1), (size_t)0); }
TEST("sorting moves pointers") { const char *w[] = {"pear", "apple", "fig", "banana"}; const char *apple = w[1]; sort_words(w, 4); CHECK_STR(w[0], "apple"); CHECK_STR(w[1], "banana"); CHECK_STR(w[2], "fig"); CHECK_STR(w[3], "pear"); CHECK(w[0] == apple); }
TEST("splitting in place") { char line[] = "split  this line"; char *parts[8]; size_t n = split(line, parts, 8); CHECK_EQ(n, (size_t)3); CHECK_STR(parts[0], "split"); CHECK_STR(parts[1], "this"); CHECK_STR(parts[2], "line"); CHECK(parts[0] == line); }
TEST("splitting stops at max") { char line[] = "a b c d e"; char *parts[2]; CHECK_EQ(split(line, parts, 2), (size_t)2); CHECK_STR(parts[0], "a"); CHECK_STR(parts[1], "b"); }
TEST("splitting nothing") { char empty[] = ""; char spaces[] = "   "; char *parts[4]; CHECK_EQ(split(empty, parts, 4), (size_t)0); CHECK_EQ(split(spaces, parts, 4), (size_t)0); }
TEST("moving a caller's pointer") { const char *text = "abcdef"; const char *c = text; advance(&c, 2); CHECK(c == text + 2); advance(&c, 100); CHECK(c == text + 6); CHECK_EQ(*c, '\0'); }

